'use client'

import * as React from 'react'
import { cn } from '@/lib/utils'

export type AspectRatioOption = {
  id: 'land' | 'square' | 'tall'
  label: string
  widthRem: string
  heightRem: string
  rect: { x: number; y: number; w: number; h: number }
}

export const MORPHING_AREA_OPTIONS: AspectRatioOption[] = [
  {
    id: 'land',
    label: 'Landscape (4:3)',
    widthRem: '17.25rem',
    heightRem: '12.9375rem',
    rect: { x: 1.5, y: 3.38, w: 15, h: 11.25 },
  },
  {
    id: 'square',
    label: 'Square (1:1)',
    widthRem: '14.9375rem',
    heightRem: '14.9375rem',
    rect: { x: 2.5, y: 2.5, w: 13, h: 13 },
  },
  {
    id: 'tall',
    label: 'Portrait (3:4)',
    widthRem: '12.9375rem',
    heightRem: '17.25rem',
    rect: { x: 3.38, y: 1.5, w: 11.25, h: 15 },
  },
]

export type MorphingAreaProps = {
  activeId?: 'land' | 'square' | 'tall'
  defaultId?: 'land' | 'square' | 'tall'
  onChange?: (option: AspectRatioOption) => void
  imageSrc?: string
  corner?: number
  morph?: number
  className?: string
}

const DEFAULT_CORNER = 18
const DEFAULT_MORPH = 50
const BASE_MORPH_MS = 520

const clamp = (val: number, min: number, max: number) => Math.min(max, Math.max(min, val))

export function MorphingArea({
  activeId,
  defaultId = 'square',
  onChange,
  imageSrc,
  corner = DEFAULT_CORNER,
  morph = DEFAULT_MORPH,
  className,
}: MorphingAreaProps) {
  const [internalIndex, setInternalIndex] = React.useState(() => {
    const idx = MORPHING_AREA_OPTIONS.findIndex((opt) => opt.id === defaultId)
    return idx >= 0 ? idx : 1
  })

  const buttonRefs = React.useRef<(HTMLButtonElement | null)[]>([])

  const currentIndex =
    activeId !== undefined
      ? Math.max(
          0,
          MORPHING_AREA_OPTIONS.findIndex((opt) => opt.id === activeId),
        )
      : internalIndex

  const currentOption = MORPHING_AREA_OPTIONS[currentIndex] ?? MORPHING_AREA_OPTIONS[1]

  const morphNormalized = clamp(morph, 0, 100) / 100
  const durationMs = Math.round(BASE_MORPH_MS * (0.3 + morphNormalized * 0.7))

  const handleSelect = (index: number, focus = false) => {
    if (index !== currentIndex) {
      if (activeId === undefined) {
        setInternalIndex(index)
      }
      onChange?.(MORPHING_AREA_OPTIONS[index])
      if (focus) {
        buttonRefs.current[index]?.focus()
      }
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    const dir =
      e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0
    if (dir) {
      e.preventDefault()
      const nextIndex = (currentIndex + dir + MORPHING_AREA_OPTIONS.length) % MORPHING_AREA_OPTIONS.length
      handleSelect(nextIndex, true)
    }
  }

  const clampedCorner = clamp(corner, 0, 40)

  return (
    <div
      className={cn('inline-flex flex-col items-center select-none font-sans gap-[0.75rem]', className)}
      style={
        {
          '--asp-ms': `${durationMs}ms`,
        } as React.CSSProperties
      }
    >
      {/* Equal-Area Morphing Stage */}
      <div className="w-[17.25rem] h-[17.25rem] flex items-center justify-center overflow-hidden">
        <div
          role="img"
          aria-label={currentOption.label}
          style={{
            width: currentOption.widthRem,
            height: currentOption.heightRem,
            borderRadius: `${clampedCorner}px`,
            ...(imageSrc && {
              backgroundImage: `url(${imageSrc})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
            }),
            transition:
              'width var(--asp-ms) cubic-bezier(0.34, 1.56, 0.64, 1), height var(--asp-ms) cubic-bezier(0.34, 1.56, 0.64, 1), border-radius var(--asp-ms) ease-out',
          }}
          className="relative bg-muted shrink-0"
        />
      </div>

      {/* Segmented ratio selector pills */}
      <div
        role="radiogroup"
        aria-label="Aspect ratio"
        onKeyDown={handleKeyDown}
        className="relative inline-flex items-center gap-1 p-1 rounded-xl bg-muted"
      >
        {/* Animated sliding indicator pill */}
        <span
          aria-hidden="true"
          style={{
            transform: `translateX(${currentIndex * 2.5}rem)`,
            transition: 'transform var(--asp-ms) cubic-bezier(0.34, 1.4, 0.64, 1)',
          }}
          className="absolute top-1 left-1 size-9 rounded-lg bg-background"
        />

        {MORPHING_AREA_OPTIONS.map((opt, i) => {
          const isSelected = i === currentIndex
          return (
            <button
              key={opt.id}
              ref={(el) => {
                buttonRefs.current[i] = el
              }}
              type="button"
              role="radio"
              aria-checked={isSelected}
              aria-label={opt.label}
              tabIndex={isSelected ? 0 : -1}
              onClick={() => handleSelect(i)}
              className={cn(
                'relative z-10 size-9 flex items-center justify-center cursor-pointer transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-lg',
                isSelected ? 'text-foreground font-semibold' : 'text-muted-foreground hover:text-foreground',
              )}
            >
              {/* Aspect thumbnail icon representation */}
              <svg viewBox="0 0 18 18" className="w-[1.125rem] h-[1.125rem] shrink-0" aria-hidden="true">
                <rect
                  x={opt.rect.x}
                  y={opt.rect.y}
                  width={opt.rect.w}
                  height={opt.rect.h}
                  rx={2}
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={1.8}
                />
              </svg>
            </button>
          )
        })}
      </div>
    </div>
  )
}
